static void activateRecommendedPlace(HWND owner,int index){const wchar_t* queries[]={L"Beijing",L"Rome",L"Cairo",L"Kyoto",L"New York City",L"Sydney"};auto matches=gPlaceCatalog.search(queries[index],1);if(matches.empty()){showUnifiedSearch(owner,queries[index]);return;}const auto& p=gPlaceCatalog.entries()[matches.front().index];navigateToReference(owner,p.latitude,p.longitude,p.zoom,p.name(gEnglish),gEnglish?L"GeoNames city reference":L"GeoNames 城市参考位置");}


